<section class="note-writing"><div class="note-actions"><span id="save-status" role="status">Saved in this browser</span><div><button id="favorite-note" aria-label="Favorite note" aria-pressed="false">&#9734;</button><button id="delete-note" aria-label="Delete note">Delete</button></div></div><label class="sr-only" for="note-title">Note title</label><input id="note-title" placeholder="An untitled thought" maxlength="160"><label class="sr-only" for="note-body">Note content</label><textarea id="note-body" placeholder="No perfect words needed. Just a place to begin…"></textarea><div class="writing-footer"><span id="word-count">0 words</span><span>Your ideas stay on this device. Export to keep a backup.</span></div></section>
